<?php namespace App\Http\Controllers\Admin; use App\Http\Controllers\Controller; use App\Http\Requests\StoreUnitRequest; use App\Http\Requests\UpdateUnitRequest; use App\Models\Unit; use App\Services\UnitService; use Illuminate\Http\Request; use Inertia\Inertia;
class UnitController extends Controller {public function __construct(private UnitService $service){} public function index(Request $r){$this->authorize('units.view');return Inertia::render('Admin/Units/Index',['units'=>$this->service->list($r->only('search')),'filters'=>$r->only('search')]);} public function create(){return Inertia::render('Admin/Units/Form',['unit'=>null]);} public function store(StoreUnitRequest $r){$this->service->create($r->validated());return redirect()->route('admin.units.index')->with('success','Unit created.');} public function edit(Unit $unit){return Inertia::render('Admin/Units/Form',['unit'=>$unit]);} public function update(UpdateUnitRequest $r,Unit $unit){$this->service->update($unit,$r->validated());return redirect()->route('admin.units.index')->with('success','Unit updated.');} public function destroy(Unit $unit){$this->authorize('units.delete');$this->service->delete($unit);return back()->with('success','Unit deleted.');}}
